class DistNamePatterns(object):
    # Base patterns
    _RAT = r'/MRBTS-\d+/RAT-\d+'
    _RUNTIME_VIEW = _RAT + r'/RUNTIME_VIEW-\d+'
    _URI_SESSION = _RAT + r'/URI-\d+/SESSION-\d+'
    _DOWNLOAD_PLAN_TASK = _URI_SESSION + r'/PLAN_VALIDATE_IND-\d+/DOWNLOAD_PLAN_TASK-\d+'
    _CHANGE_CONTEXT = _DOWNLOAD_PLAN_TASK + r'/CHANGE_CONTEXT-\d+'
    _CABINET = _RAT + r'/BTS_L-\d+/EQM_L-\d+/CABINET_L-\d+'

    # Rest of patterns
    MRBTS = r'/MRBTS-\d+$'
    MRBTS_A = _RAT + r'/BTS_L-\d+/BTS_CONF-\d+/NP-\d+/SCF-\d+/MRBTS_A-(?P<BTS_ID>\d+)$'
    BTS_INFO = _RAT + r'/MCTRL-\d+/BBTOP_M-\d+/MRBTS_M-\d+/(GN|WN|LN|NR)BTS_M-\d+'

    CELL_INFO = _RUNTIME_VIEW + r'/MRBTS_\w+-\d+/(GN|WN|LN|NR)BTS_\w+-\d+/.*(GN|WN|LN|NR)CELL?_[RL]-\d+$'
    GSM_CELL_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/GNBTS_R-\d+/GNBCF_R-\d+/GNCEL_CONF_M-\d+/GNCEL_R-\d+$'
    WCDMA_CELL_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/WNBTS_R-\d+/WNCEL_R-\d+$'
    LTE_CELL_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/LNBTS_R-\d+/LNCEL_R-\d+$'
    NR_CELL_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/NRBTS_R-\d+/NRCELL_R-\d+$'
    SINGLE_CELL_INFO = _RUNTIME_VIEW + r'/MRBTS_\w+-\d+/(GN|WN|LN|NR)BTS_\w+-\d+/.*(GN|WN|LN|NR)CELL?_[RL]-' \
                                       r'{global_cell_id}$'
    BLOCK_CELL_REQUEST = _URI_SESSION + r'/BLOCK_IND-\d+$'
    UNBLOCK_CELL_REQUEST = _URI_SESSION + r'/UNBLOCK_IND-\d+$'
    CELL_LOCK_UNLOCK_REQUEST = _CHANGE_CONTEXT + r'/.*-{global_cell_id}$'

    NRBTS_INFO = r'MRBTS-\d+/RAT-\d+/NRTS-\d+/NRBTS_L-\d+$'

    BBMOD_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/EQM_R-\d+/APEQM_R-\d+/CABINET_R-\d+/BBMOD_R-\d+$'

    RMOD_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/EQM_R-\d+/APEQM_R-\d+/(ASI)?RMOD_R-\d+$'
    SINGLE_RMOD_INFO = _RUNTIME_VIEW + r'/MRBTS_R-\d+/EQM_R-\d+/APEQM_R-\d+/(ASI)?RMOD_R-{rmod_id}$'
    RMOD_L_INFO = r'/MRBTS-\d+/RAT-\d+/BTS_L-\d+/EQM_L-\d+/(ASI)?RMOD_L-\d+$'

    PLAN_ACTIVATE_IND = _URI_SESSION + r'/PLAN_ACTIVATE_IND-\d+$'
    _DELTA = r'/MRBTS-\d+/RAT-\d+/BTS_.*/BTS_CONF-\d+/NP-\d+/DELTA-\d+'
    DELTA = _DELTA + r'$'
    DELTA_CHANGE_CONTEXT = _DELTA + r'/CHANGE_CONTEXT-\d+'

    RESET_IND = _URI_SESSION + r'/RESET_IND-\d+$'
    RESET_IND_RESULT = _URI_SESSION + r'/RESET_IND-\d+/RESULT-\d+$'
    RESET_IND_ASIR = r'/MRBTS-\d+/RAT-\d+/CCI-\d+/RESET_IND-\d+'

    SW_UPDATE_IND = _URI_SESSION + r'/SW_UPDATE_IND-\d+$'
    SW_UPDATE_RESET_TYPE = _RAT + r'/SWM-\d+/SW_POSTPROCESSING_REQ-\d+/SW_UPDATE_RESET_TYPE-\d+$'
    SW_ROLLBACK_IND = _URI_SESSION + r'/SW_ROLLBACK_IND-\d+$'
    ROLE_SWITCH_IND = _URI_SESSION + r'/ROLE_SWITCH_IND-\d+$'
    SW_DOWNLOAD_REQ = r'/MRBTS-\d+/RAT-\d+/SWM-\d+/SW_DOWNLOAD_REQ-\d+$'
    SW_DOWNLOAD_RESULT = r'/MRBTS-\d+/RAT-\d+/SWM-\d+/SW_DOWNLOAD_REQ-\d+/SW_DOWNLOAD_RESULT-\d+$'
    SW_DOWNLOAD_STATUS = r'/MRBTS-\d+/RAT-\d+/SWM-\d+/SW_DOWNLOAD_REQ-\d+/SW_DOWNLOAD_STATUS-\d+$'

    SWCONFIG = _CABINET + r'/SMOD_L-\d+/SWCONFIG_L-\d+$'
    RESET_PROCEDURE = _RUNTIME_VIEW + r'/MRBTS_R-\d+/RESET_PROCEDURE_R-\d+'
    HWRESETREQ = _CHANGE_CONTEXT + r'/HWRESETREQ_A-\d+$'

    CHANGE_CONTEXT = _CHANGE_CONTEXT + r'$'
    SFP_STATE_REQUEST = _CHANGE_CONTEXT + r'/LANE_A-\d+$'
    CABLINK = _RUNTIME_VIEW + r'/MRBTS_R-\d+/EQM_R-\d+/HWTOP_R-\d+/CABLINK_R-\d+$'
    RNW_DATA = r'/MRBTS-\d+/RAT-\d+/BTS_L-\d+/BTS_CONF-\d+/NP-\d+/RNW_DATA-\d+$'
    CPRI_MASTER = _CABINET + r'/(BB|S)MOD_L-\d+/CONNECTOR_L-\d+/HWPORT_L-\d+/CPRI_MASTER_SM_PORTCONF_L-\d+'
    OPT_PORTCONF = _CABINET + r'/(BB|S)MOD_L-\d+/CONNECTOR_L-\d+/OPT_PORTCONF_L-\d+$'
    _alarm_fri = r'/MRBTS-\d+/RAT-\d+/FRI-\d+/ALARM-\d+$'
    _alarm_lts = r'/MRBTS-\d+/RAT-\d+/LTS-\d+/.*?/ALARM_L-\d+$'
    ALARM = r'({})|({})'.format(_alarm_fri, _alarm_lts)
    # Other option - need to confirm with testers/VA which one we should use
    # CELL_INFO_v2 = r'.*(GN|WN|LN|NR)BTS_M-\d+/CELL_M-\d+$'  # phy cell id
    # SINGLE_CELL_INFO_v2 = r'.*{bts_name}_M-\d+/CELL_M-{physical_cell_id}$'

    # Not used
    # RESET_IND_ACK = r'/MRBTS-\d+/RAT-\d+/URI-\d+/SESSION-\d+/RESET_IND-\d+/ACK-\d+'
    # RESET_REQ = r'/MRBTS-\d+/RAT-\d+/URI-\d+/ENTITY_RESET_REQ-\d+$'
    # ACTIVATION_REQ = r'/MRBTS-\d+/RAT-\d+/URI-\d+/ACTIVATION_REQ-\d+'

    # Backup distnames
    # /MRBTS-1/RAT-1/SWM-1/SW_DOWNLOAD_REQ-1
    # /MRBTS-1/RAT-1/SWM-1/SW_DOWNLOAD_REQ-1/SW_DOWNLOAD_STATUS-1
    # /MRBTS-1/RAT-1/URI-1/SESSION-131297/SW_UPDATE_IND-0/ACK-1
    # /MRBTS-1/RAT-1/URI-1/SESSION-131297/SW_UPDATE_IND-0
